class Solution {
public:
    bool isConsecutive(std::vector<int>& arr) {
        int n = arr.size();
        if (n <= 1) return true;
        std::sort(arr.begin(), arr.end());
        for (int i = 0; i < n - 1; ++i) {
            if (arr[i] == arr[i + 1]) return false;
            if (arr[i] + 1 != arr[i + 1]) return false;
        }
        return true;
    }
};

